    custodyPdfChainNoData: '— (dati non inseriti)',
    custodyPdfLegalNote: 'I dati in questo documento sono stati inseriti manualmente dall\'utente e attestano le circostanze di acquisizione del file digitale. La corrispondenza delle hash SHA-256 costituisce prova di integrità ai sensi dell\'art. 491-bis c.p. Il presente documento non sostituisce una perizia tecnica informatica disposta dall\'Autorità Giudiziaria.',
