    shotPdfCaptionBase: 'Screenshot del pannello Proprietà del file, acquisito direttamente dal sistema operativo del sottoscritto. L\'immagine documenta i timestamp NTFS originali del file (Creazione, Ultima modifica, Ultimo accesso) e gli attributi di sistema. Costituisce prova documentale ai sensi dell\'art. 2712 c.c. e prova atipica ai sensi dell\'art. 189 c.p.p. Il contenuto NON è stato trascritto né reinterpretato dall\'operatore.',
    shotPdfNormRef: 'Riferimenti normativi: art. 2712 c.c. (riproduzioni informatiche come prova documentale) — art. 189 c.p.p. (prove atipiche, ammissibilità dello screenshot) — art. 491-bis c.p. (integrità digitale — l\'hash SHA-256 certifica il contenuto in ogni caso).',
    shotInfoBtnTitle: 'Nota interna — solo per l\'utente dell\'app',
    shotInternalNoteTitle: '⚠️ NOTA INTERNA — solo per l\'utente',
    shotInternalNoteText: 'I metadati del filesystem — lastModified, dimensione, tipo MIME, nome originale — sono indicativi del contesto di acquisizione. Possono cambiare legittimamente in seguito a operazioni ordinarie del sistema operativo quali copia, trasferimento o conversione di formato.\n\nSi precisa in particolare che la data Last Modified può essere aggiornata automaticamente dal sistema operativo durante il trasferimento del file da un dispositivo all\'altro — ad esempio da smartphone a PC — e può quindi non corrispondere alla data di registrazione originale.\n\nPer questo motivo i metadati del filesystem corroborano ma non sostituiscono l\'hash SHA-256: l\'hash certifica l\'integrità del contenuto binario in modo indipendente da qualsiasi metadato e rimane valida anche se la data Last Modified cambia.\n\nLo screenshot Proprietà del file Windows documenta i timestamp NTFS che il browser non può leggere. Il suo peso probatorio è elevato come prova documentale ai sensi dell\'art. 2712 c.c.; in caso di disconoscimento della controparte (art. 214-216 c.p.c.) l\'hash SHA-256 rimane comunque prova di integrità ai sensi dell\'art. 491-bis c.p.',
    shotInternalNoteClose: 'Chiudi',
