    proofFromFascHint: 'I PDF aprono il visualizzatore completo con OCR e annotazioni. Gli altri file vengono aperti direttamente nel modulo prova.',
    proofFromFascHintMedia: 'Seleziona un file audio, video o immagine dal fascicolo per creare una prova. I documenti PDF vanno aggiunti tramite Atto da Fascicolo.',
