    donTitle: 'Sostieni UX GIUSTIZIA',
    donSubtitle: 'UX GIUSTIZIA è uno strumento gratuito per la tutela dei diritti.\n\nL\'app aiuta a organizzare prove e documenti per rendere più semplice dimostrare errori, ingiustizie o possibili abusi, anche di natura sistematica, all\'interno dei sistemi amministrativi e giudiziari.\n\nIl progetto è indipendente e sviluppato senza finanziamenti istituzionali. L\'app funziona completamente offline: tutti i dati restano esclusivamente nella memoria del dispositivo dell\'utente.\n\nSe credi nell\'importanza della trasparenza e della difesa dei diritti, considera una piccola donazione per sostenere lo sviluppo e il miglioramento continuo del progetto.',
