    factGuideSecPec: '6. Archivio PEC riusabile',
    factGuidePec: 'L\'<b>Archivio PEC</b> contiene una sola copia di ogni PEC dell\'esponente con corpo, ricevuta di accettazione e ricevuta di consegna. Quando dal Fatto premi <b>📧 Richiama PEC</b> puoi creare in un colpo solo l\'<b>Atto</b> (il messaggio inviato — è la tua presa di posizione) e/o la <b>Prova</b> (le ricevute con timestamp — documentano che la notifica è avvenuta). I file non vengono duplicati: l\'app crea puntatori al file originale, così la stessa PEC può comparire in più Fatti senza occupare spazio extra. Le card mostrano il badge cliccabile <b>📧 Da archivio PEC</b> che riapre la PEC sorgente.',

