    custodyPdfLegalNote: 'The data in this document were manually entered by the user and attest to the circumstances of digital file acquisition. SHA-256 hash correspondence constitutes integrity evidence per Art. 491-bis Italian Penal Code. This document does not replace a technical forensic expert opinion ordered by the Judicial Authority.',
    firmaModeTip: 'Choose how you will sign the generated PDF documents',
    firmaModeZipTip: '"Digital signature applied" badge included — for those who will sign the ZIP archive with a digital signature',
