    shotPdfCaptionBase: 'Screenshot of the file Properties panel, captured directly from the undersigned\'s operating system. The image documents the original NTFS timestamps (Created, Modified, Accessed) and system attributes. It constitutes documentary evidence pursuant to Art. 2712 c.c. and atypical evidence pursuant to Art. 189 c.p.p. The content has NOT been transcribed or reinterpreted by the operator.',
    shotPdfNormRef: 'Normative references: Art. 2712 c.c. (computer reproductions as documentary evidence) — Art. 189 c.p.p. (atypical evidence, admissibility of screenshot) — Art. 491-bis c.p. (digital integrity — SHA-256 hash certifies content in any case).',
    shotInfoBtnTitle: 'Internal note — for app user only',
    shotInternalNoteTitle: '⚠️ INTERNAL NOTE — for user only',
    shotInternalNoteText: 'Filesystem metadata — lastModified, size, MIME type, original name — are indicative of the acquisition context. They can legitimately change due to ordinary OS operations such as copying, transferring or converting format.\n\nIn particular, the Last Modified date can be automatically updated by the operating system during file transfer from one device to another — for example from smartphone to PC — and may therefore not correspond to the original recording date.\n\nFor this reason filesystem metadata corroborate but do not replace the SHA-256 hash: the hash certifies the integrity of the binary content independently of any metadata and remains valid even if the Last Modified date changes.\n\nThe Windows File Properties screenshot documents NTFS timestamps that the browser cannot read. Its evidential weight is high as documentary evidence pursuant to Art. 2712 c.c.; in the event of contestation by the counterparty (Art. 214-216 c.p.c.) the SHA-256 hash still constitutes proof of integrity pursuant to Art. 491-bis c.p.',
    shotInternalNoteClose: 'Close',
