    addProof: '+ Proof',
    addProofExternal: '+ External Proof',
    badgeInDossier: 'In dossier',
    badgeExternal: 'External',
    badgePec: 'From PEC',
    factGuideButton: 'Guide',
    factGuideButtonTitle: 'Guide: how to distinguish Acts, Proofs and In dossier / External badges',
    factGuideTitle: 'Guide: Acts vs Proofs, In dossier vs External',
    factGuideIntro: "This modal is the analytical core of the app. Here you build the evidentiary argument for a single Fact. To use it well you need two clear distinctions.",
    factGuideSecActProof: '1. Act vs Proof — the golden rule',
    factGuideRule: '<b>Ask yourself</b>: does this content <b>take a position</b> on the fact, or does it <b>describe / document</b> it?',
    factGuideRuleAct: '<b>Takes a position</b> (asserts, denies, omits, requests, declares) → it is an <b>Act</b>.',
    factGuideRuleProof: '<b>Describes, documents, records reality</b> → it is a <b>Proof</b>.',
    factGuideSecExamples: '2. Practical cases',
    factGuideExPec: '<b>EXTERNAL ACT</b><br>certified emails (PEC), formal notices, demand letters, complaints, motions, briefs. Even if they "prove" something, they prove it as acts.',
    factGuideExDoc: '<b>EXTERNAL PROOF</b><br>medical reports, party expert opinions, invoices, receipts, bank statements, certificates. They document a material fact, they do not take a position.',
    factGuideExMedia: '<b>EXTERNAL PROOF</b><br>photos, videos, ambient audio, recordings of third parties, intercepts. Always proof, never act.',
    factGuideExOwnDecl: '<b>EXTERNAL ACT</b><br>your own recorded declaration (e.g. you record yourself formally declaring something). Recommended practice: upload the audio as EXTERNAL PROOF and create an EXTERNAL ACT PDF (the signed transcription) linked to the proof.',
    factGuideExTransc: '<b>EXTERNAL PROOF</b><br>transcription of someone else\'s conversation, even if the final file is a PDF. The content is documentation of a fact, not your own position.',
    factGuideExActDoss: '<b>ACT FROM DOSSIER</b><br>judge orders, decrees, rulings, judgments, prosecutor acts, official records, party acts already filed. Everything already in the institutional files.',
    factGuideExProofDoss: '<b>PROOF FROM DOSSIER</b><br>exhibits, court expert opinions, photos/videos acquired during investigations, authorized intercepts, attachments already filed with an act. Evidentiary material already in the official dossier.',
    factGuideCatActExt: 'EXTERNAL ACT',
    factGuideCatActExt1: '<b>Your formal acts</b>: PEC, formal notices, demand letters, complaints, motions, briefs.',
    factGuideCatActExt2: '<b>Your recorded declarations</b>: audio or video where you formally declare something (recommended: upload audio as EXTERNAL PROOF and create an act PDF with the signed transcription).',
    factGuideCatProofExt: 'EXTERNAL PROOF',
    factGuideCatProofExt1: '<b>Documents</b>: medical reports, party expert opinions, invoices, receipts, bank statements, certificates.',
    factGuideCatProofExt2: '<b>Media and recordings</b>: photos, videos, ambient audio, recordings of third parties, intercepts and their transcriptions (also as PDF).',
    factGuideCatActDoss: 'ACT FROM DOSSIER',
    factGuideCatActDoss1: '<b>Judge measures</b>: decrees, orders, judgments.',
    factGuideCatActDoss2: '<b>Prosecutor and judicial police acts</b>: requests, decrees, official records (search, seizure, statements, interrogation).',
    factGuideCatActDoss3: '<b>Party acts already filed</b>: briefs, motions, appeals, pleadings.',
    factGuideCatProofDoss: 'PROOF FROM DOSSIER',
    factGuideCatProofDoss1: '<b>Exhibits and technical material</b>: corpora delicti, traces, samples.',
    factGuideCatProofDoss2: '<b>Court expert opinions</b> and consultancies ordered by the body.',
    factGuideCatProofDoss3: '<b>Institutional media</b>: photos/videos acquired during investigations, authorized intercepts.',
    factGuideCatProofDoss4: '<b>Attachments already filed</b> together with an act.',
    factGuideCatNote: 'The four groups correspond to the four buttons you find in the Acts and Proofs columns of the modal.',
    factGuideSecAmbig: '3. Ambiguous case: the same PEC as Act AND as Proof',
    factGuideAmbig: 'A PEC can serve you twice: as an <b>act</b> (the content of the formal notice) and as a <b>proof</b> (proof that the notification occurred on day X). Clean solution: create <b>two distinct entities</b> — an Act and a Proof — that can share the same attached file. Then link them to each other in the Fact panel.',
    factGuideSecBadges: '4. In dossier vs External — the colored badges',
    factGuideBadgeIn: '${IN} = act/proof <b>already in the official dossier</b> (filed or present in the institutional files).',
    factGuideBadgeExt: '${EXT} = act/proof <b>external to the dossier</b> (your own production, not yet filed, or document that exists only with you).',
    factGuideBadgeNote: 'The status is automatic: it depends on the presence of a source file linked to the dossier, not on a flag you set. When you file an external act/proof, the app updates the badge.',
    factGuideSecLogic: '5. Logical state of the Fact',
    factGuideLogic: 'The app automatically computes the Fact state by crossing the positions of Acts (asserts / denies / omits) with the relations of Proofs (confirms / contradicts / describes):',
    factGuideLogicCoh: '<b>COHERENT</b> — acts and proofs say the same thing.',
    factGuideLogicInc: '<b>INCOHERENCE</b> — an act asserts X but proofs contradict it (red signal, possible abuse).',
    factGuideLogicOmi: '<b>OMISSION</b> — an act omits what proofs demonstrate (orange signal).',
    factGuideLogicNop: '<b>NO_PROOFS</b> — the fact has no proofs linked yet.',
    factGuideSecWorkflow: '6. Recommended workflow',
    factGuideWf1: 'Create the <b>Fact</b> and briefly describe it.',
    factGuideWf2: 'Add the <b>Circumstances</b> (temporal, modal, subjective, technical) that articulate it.',
    factGuideWf3: 'Link the <b>Acts</b> (from the dossier or external) and specify the position of each.',
    factGuideWf4: 'Link the <b>Proofs</b> (from the dossier or external) and specify whether they confirm or contradict.',
    factGuideWf5: 'Read the logical state badges: they tell you where there is incoherence or omission to challenge.',
    factGuideTip: 'Tip',
    factGuideTipText: 'do not waste time deciding the "right type" before knowing how you will use the document. Upload it, link it, then if needed duplicate it as distinct Act/Proof. The app\'s IDProb logic is designed for this.',
    proofFromFascBtn: '+ Proof from Dossier',
    proofFromFascTitle: 'Create Proof from File',
    proofFromFascPickerTitle: 'Select File from Dossier',
    proofFromFascHint: 'PDFs open the full viewer with OCR and annotations. Other files open directly in the proof form.',
    proofFromFascHintMedia: 'Select an audio, video or image file from the dossier to create a proof. PDF documents should be added via Act from Dossier.',
    createProofBtn: 'Create Proof',
